from pathlib import Path
p=Path('/mnt/d/OpenKernelChallenge/serving/swarm_2026-11-16/moe')
s=(p/'humming_probe.py').read_text()
s=s.replace("import argparse,ast,hashlib,json,sys,time", "import argparse,ast,hashlib,json,sys,time,importlib.util")
s=s.replace("    humm=prepare_humming(raw,torch)", "    spec=importlib.util.spec_from_file_location('standalone',HERE/'submission_humming_fp32_v1.py')\n    standalone=importlib.util.module_from_spec(spec);spec.loader.exec_module(standalone)\n    norm=torch.linspace(-.5,.5,args.hidden,device='cuda',dtype=torch.bfloat16)\n    weights={'post_norm_w':norm}\n    for prefix in ('w13','w2'):\n        weights[prefix]=getattr(raw,prefix+'_weight')\n        weights[prefix+'_sf']=getattr(raw,prefix+'_weight_scale')\n        gs=getattr(raw,prefix+'_weight_scale_2')\n        gs.mul_(torch.linspace(.25,2.0,args.experts,device='cuda'))\n        weights[prefix+'_gs']=gs\n    state=standalone.prepare(weights)\n    del weights\n    humm=state['layer']")
s=s.replace("norm=torch.linspace(.5,1.5,args.hidden,device='cuda',dtype=torch.bfloat16)", "norm=state['norm_w']")
s=s.replace("eps=1e-6", "eps=1e-8")
s=s.replace("def candidate():return finish(*indexed(humm,x,local,torch))", "def candidate():return standalone.kernel_fn({'hidden_states':x,'topk_ids':ids,'topk_weights':scores,'config':{'local_start':0,'local_count':args.experts,'top_k':8}},state)")
s=s.replace("        b=baseline();a=candidate();torch.cuda.synchronize()", "        b=baseline();a=candidate();torch.cuda.synchronize()\n        # Both graphs replay on freshly changed activations, route IDs and scores.\n        gb,ob=capture(baseline,torch);ga,oa=capture(candidate,torch)\n        for replay_seed in (221,239,251):\n            torch.manual_seed(replay_seed)\n            x.copy_(torch.randn_like(x)/20)\n            ids.copy_(torch.tensor(make_routes(m,8,args.experts*8,8,pattern,replay_seed),device='cuda',dtype=torch.int32))\n            scores.copy_(torch.rand_like(scores));scores.div_(scores.sum(-1,keepdim=True))\n            gb.replay();ga.replay();torch.cuda.synchronize()\n            dd=oa.float()-ob.float()\n            rr=(dd.norm()/ob.float().norm().clamp_min(1e-20)).item();aa=dd.abs().max().item()\n            assert torch.isfinite(oa).all() and rr<=.003 and aa<=.03125,(m,pattern,replay_seed,rr,aa)\n        b=ob;a=oa")
s=s.replace("'scope':'component only; original BF16 global-scale output boundaries; no input quantization'", "'scope':'standalone exact file; K4096 scale stress, changed graph inputs, FP32 accumulation and no Stream-K', 'artifact_sha256':hashlib.sha256((HERE/'submission_humming_fp32_v1.py').read_bytes()).hexdigest()")
(p/'standalone_probe.py').write_text(s)
l=(p/'launch_humming.py').read_text(encoding='utf-8-sig').replace("'humming_probe.py'", "'standalone_probe.py'")
(p/'launch_standalone.py').write_text(l)
